import{_ as e,o as i,c as n,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Program Dasar Kemajuan Bersama Sepuluh Ribu Ras","description":"","frontmatter":{},"headers":[],"relativePath":"id/05-万族共进基本纲领.md","filePath":"id/05-万族共进基本纲领.md","lastUpdated":null}'),t={name:"id/05-万族共进基本纲领.md"};function s(u,a,d,m,k,l){return i(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="program-dasar-kemajuan-bersama-sepuluh-ribu-ras" tabindex="-1">Program Dasar Kemajuan Bersama Sepuluh Ribu Ras <a class="header-anchor" href="#program-dasar-kemajuan-bersama-sepuluh-ribu-ras" aria-label="Permalink to &quot;Program Dasar Kemajuan Bersama Sepuluh Ribu Ras&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>05</td></tr><tr><td>Modul</td><td>Prinsip Umum dan Pengaturan Inti</td></tr><tr><td>Kata Kunci Utama</td><td>Sepuluh Ribu Ras, Kemajuan Bersama, Kesetaraan Ras, Evolusi Kerja Sama, Republik</td></tr></tbody></table><h2 id="i-definisi-dan-ruang-lingkup-sepuluh-ribu-ras" tabindex="-1">I. Definisi dan Ruang Lingkup Sepuluh Ribu Ras <a class="header-anchor" href="#i-definisi-dan-ruang-lingkup-sepuluh-ribu-ras" aria-label="Permalink to &quot;I. Definisi dan Ruang Lingkup Sepuluh Ribu Ras&quot;">​</a></h2><p>&quot;Sepuluh Ribu Ras&quot; adalah sebutan umum untuk semua bentuk kehidupan dengan potensi persepsi dan evolusi di Kosmos Asli dari Sepuluh Ribu Roh dan Jangkar Seimbang. &quot;Sepuluh Ribu&quot; tidak merujuk secara pasti pada sepuluh ribu ras, melainkan menyatakan jumlahnya yang sangat banyak, mencakup semua bentuk kehidupan yang dikenal maupun tidak dikenal. Ruang lingkup Sepuluh Ribu Ras mencakup, tetapi tidak terbatas pada: Ras Manusia dan berbagai ras humanoid, kehidupan energi, entitas kesadaran, kehidupan mekanis, kehidupan cerdas tipe tumbuhan, kehidupan anomali, ras campuran antar-bidang, dll.</p><p>Peradaban simbiosis memegang teguh prinsip &quot;kesetaraan bentuk kehidupan&quot;, dan tidak menggunakan komposisi material, tingkat energi, atau kompleksitas kesadaran kehidupan sebagai kriteria untuk membagi tinggi-rendah atau mulia-hina. Ras apa pun, terlepas dari tingkat kultivasi rata-rata individunya, jumlah populasinya, atau lamanya sejarahnya, menikmati status dan hak yang setara dalam peradaban simbiosis.</p><h2 id="ii-gagasan-inti-kemajuan-bersama-sepuluh-ribu-ras" tabindex="-1">II. Gagasan Inti Kemajuan Bersama Sepuluh Ribu Ras <a class="header-anchor" href="#ii-gagasan-inti-kemajuan-bersama-sepuluh-ribu-ras" aria-label="Permalink to &quot;II. Gagasan Inti Kemajuan Bersama Sepuluh Ribu Ras&quot;">​</a></h2><p>Kemajuan bersama Sepuluh Ribu Ras adalah salah satu tujuan inti Peradaban Simbiosis Jangkar, dan gagasan dasarnya dapat diringkas dalam empat poin berikut:</p><ol><li><strong>Evolusi bukan permainan jumlah nol antar-ras</strong>: Evolusi satu ras tidak mengorbankan ras lain; sebaliknya, kerja sama antar-ras dapat menghasilkan efek evolusi sinergis.</li><li><strong>Setiap ras memiliki keunggulan evolusi yang unik</strong>: Berbagai ras telah mengembangkan karakteristik dan bakat masing-masing selama evolusi panjang, dan karakteristik ini adalah kekayaan berharga bagi keragaman evolusi kosmos.</li><li><strong>Ras yang tertinggal berhak mendapatkan dukungan</strong>: Untuk ras dengan tingkat evolusi yang lebih rendah, peradaban simbiosis berkewajiban memberikan dukungan dalam pendidikan, sumber daya, teknologi, dll., membantu mereka menemukan jalur evolusi mereka sendiri.</li><li><strong>Ras yang maju berkewajiban memikul tanggung jawab</strong>: Ras dengan tingkat evolusi yang lebih tinggi memikul lebih banyak tanggung jawab publik dalam peradaban simbiosis, termasuk pemeliharaan titik jangkar, pewarisan pengetahuan, perlindungan peradaban, dll.</li></ol><h2 id="iii-prinsip-dasar-kemajuan-bersama-sepuluh-ribu-ras" tabindex="-1">III. Prinsip Dasar Kemajuan Bersama Sepuluh Ribu Ras <a class="header-anchor" href="#iii-prinsip-dasar-kemajuan-bersama-sepuluh-ribu-ras" aria-label="Permalink to &quot;III. Prinsip Dasar Kemajuan Bersama Sepuluh Ribu Ras&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th><th>Persyaratan Spesifik</th></tr></thead><tbody><tr><td>Prinsip Kesetaraan Ras</td><td>Semua ras setara dalam status hukum dan hak evolusi</td><td>Larangan diskriminasi ras, jabatan publik terbuka untuk semua ras</td></tr><tr><td>Prinsip Penghormatan Budaya</td><td>Menghormati tradisi budaya dan cara hidup setiap ras</td><td>Tidak memaksakan asimilasi budaya, mendukung pewarisan dan pengembangan budaya ras</td></tr><tr><td>Prinsip Saling Melengkapi Keunggulan</td><td>Mendorong ras untuk berkolaborasi dengan memanfaatkan keunggulan masing-masing</td><td>Membuat basis data keahlian ras, mempromosikan proyek kerja sama antar-ras</td></tr><tr><td>Prinsip Dukungan bagi yang Tertinggal</td><td>Memberikan dukungan tambahan bagi ras dengan tingkat evolusi lebih rendah</td><td>Membuat dana pengembangan ras, memberikan pendidikan terarah dan distribusi sumber daya</td></tr><tr><td>Prinsip Otonomi dan Pemerintahan Bersama</td><td>Urusan internal ras bersifat otonom, urusan antar-ras diperintah bersama</td><td>Setiap ras memiliki hak legislatif internal, urusan publik diputuskan oleh institusi republik</td></tr><tr><td>Prinsip Penyelesaian Konflik Secara Damai</td><td>Konflik antar-ras diselesaikan dengan cara damai</td><td>Larangan perang antar-ras, konflik diajukan ke arbitrase Pengadilan Jangkar</td></tr></tbody></table><h2 id="iv-jalur-implementasi-kemajuan-bersama-sepuluh-ribu-ras" tabindex="-1">IV. Jalur Implementasi Kemajuan Bersama Sepuluh Ribu Ras <a class="header-anchor" href="#iv-jalur-implementasi-kemajuan-bersama-sepuluh-ribu-ras" aria-label="Permalink to &quot;IV. Jalur Implementasi Kemajuan Bersama Sepuluh Ribu Ras&quot;">​</a></h2><p>Kemajuan bersama Sepuluh Ribu Ras bukanlah sekadar slogan, melainkan diimplementasikan secara bertahap melalui jalur spesifik berikut:</p><h3 id="_4-1-pendidikan-umum" tabindex="-1">4.1 Pendidikan Umum <a class="header-anchor" href="#_4-1-pendidikan-umum" aria-label="Permalink to &quot;4.1 Pendidikan Umum&quot;">​</a></h3><p>Membangun sistem pendidikan simbiosis antar-ras, di mana remaja dari semua ras dapat menerima pendidikan evolusi dasar secara gratis. Konten pendidikan mencakup metode dasar dari Tiga Ratus Sistem Kultivasi, etika anti-predasi, Konstitusi Peradaban Simbiosis, pengetahuan umum kosmos, dll. Pada saat yang sama, menghormati tradisi pendidikan budaya setiap ras, mengizinkan penyelenggaraan pendidikan dengan karakteristik ras di luar pendidikan umum.</p><h3 id="_4-2-berbagi-sumber-daya" tabindex="-1">4.2 Berbagi Sumber Daya <a class="header-anchor" href="#_4-2-berbagi-sumber-daya" aria-label="Permalink to &quot;4.2 Berbagi Sumber Daya&quot;">​</a></h3><p>Melalui sistem kontrak berbasis produksi, mendistribusikan sumber daya kultivasi kosmik secara terpadu sesuai dengan populasi ras, kebutuhan evolusi, dan tingkat kontribusi. Untuk ras yang kekurangan sumber daya, melakukan distribusi sumber daya antar-bidang melalui jaringan titik jangkar. Melarang ras mana pun memonopoli sumber daya kultivasi publik.</p><h3 id="_4-3-penelitian-teknologi-bersama" tabindex="-1">4.3 Penelitian Teknologi Bersama <a class="header-anchor" href="#_4-3-penelitian-teknologi-bersama" aria-label="Permalink to &quot;4.3 Penelitian Teknologi Bersama&quot;">​</a></h3><p>Mendorong penelitian kerja sama teknologi antar-ras, terutama proyek penelitian yang menggabungkan kemampuan bawaan berbagai ras dengan rekayasa hukum. Peradaban simbiosis mendirikan &quot;Dana Penelitian Bersama Sepuluh Ribu Ras&quot;, membiayai tim penelitian antar-ras. Hasil penelitian dibuka secara gratis untuk semua ras.</p><h3 id="_4-4-mobilitas-bakat" tabindex="-1">4.4 Mobilitas Bakat <a class="header-anchor" href="#_4-4-mobilitas-bakat" aria-label="Permalink to &quot;4.4 Mobilitas Bakat&quot;">​</a></h3><p>Memecahkan hambatan bakat antar-ras, mengizinkan kultivator untuk bergerak dan bertukar secara bebas di antara area pemukiman ras yang berbeda. Membangun sistem mentor antar-ras, di mana kultivator tingkat lanjut dapat membimbing kultivator pemula dari ras lain.</p><h3 id="_4-5-partisipasi-republik" tabindex="-1">4.5 Partisipasi Republik <a class="header-anchor" href="#_4-5-partisipasi-republik" aria-label="Permalink to &quot;4.5 Partisipasi Republik&quot;">​</a></h3><p>Parlemen Republik Sepuluh Ribu Ras mendistribusikan kursi secara terpadu sesuai dengan populasi ras dan tingkat kontribusi, memastikan ras kecil juga memiliki saluran suara. Keputusan parlemen mengadopsi kombinasi konsensus melalui negosiasi dan pemungutan suara mayoritas, dan hal-hal yang berkaitan dengan kepentingan mendasar suatu ras memerlukan persetujuan ras terkait.</p><h2 id="v-kebijakan-untuk-ras-khusus" tabindex="-1">V. Kebijakan untuk Ras Khusus <a class="header-anchor" href="#v-kebijakan-untuk-ras-khusus" aria-label="Permalink to &quot;V. Kebijakan untuk Ras Khusus&quot;">​</a></h2><p>Untuk ras dalam situasi khusus, peradaban simbiosis mengadopsi kebijakan yang berbeda:</p><ul><li><strong>Ras Terancam Punah</strong>: Membuat rencana perlindungan ras, memberikan dukungan sumber daya darurat dan perlindungan habitat, membantu mereka memulihkan populasi</li><li><strong>Ras Kehidupan Anomali</strong>: Mengevaluasi dan menempatkan sesuai dengan alur penanganan standar tiga jenis kehidupan anomali, memastikan hak evolusi mereka terlindungi</li><li><strong>Ras Campuran Antar-bidang</strong>: Mengakui identitas ras ganda mereka, menjamin hak setara mereka di kedua budaya ras</li><li><strong>Ras Eks-Predator</strong>: Untuk ras yang secara historis menganut predasionisme, setelah menyelesaikan transformasi etika dan konversi sistem, diberikan status yang sepenuhnya setara, tidak melakukan diskriminasi retrospektif historis</li></ul><h2 id="vi-indikator-pengukuran-kemajuan-bersama-sepuluh-ribu-ras" tabindex="-1">VI. Indikator Pengukuran Kemajuan Bersama Sepuluh Ribu Ras <a class="header-anchor" href="#vi-indikator-pengukuran-kemajuan-bersama-sepuluh-ribu-ras" aria-label="Permalink to &quot;VI. Indikator Pengukuran Kemajuan Bersama Sepuluh Ribu Ras&quot;">​</a></h2><p>Peradaban simbiosis telah membangun &quot;Indeks Kemajuan Bersama Sepuluh Ribu Ras&quot;, mengukur kemajuan kemajuan bersama Sepuluh Ribu Ras dari dimensi berikut:</p><table tabindex="0"><thead><tr><th>Dimensi</th><th>Indikator</th><th>Tujuan</th></tr></thead><tbody><tr><td>Tingkat Cakupan Evolusi</td><td>Proporsi ras yang terhubung ke sistem kultivasi</td><td>100%</td></tr><tr><td>Tingkat Keseimbangan Tingkat</td><td>Koefisien perbedaan tingkat rata-rata setiap ras</td><td>Terus menurun</td></tr><tr><td>Kepadatan Kerja Sama</td><td>Jumlah dan kedalaman proyek kerja sama antar-ras</td><td>Terus meningkat</td></tr><tr><td>Vitalitas Budaya</td><td>Aktivitas pewarisan dan inovasi budaya ras</td><td>Menjaga keragaman</td></tr><tr><td>Tingkat Kejadian Konflik</td><td>Frekuensi terjadinya konflik antar-ras</td><td>Terus menurun</td></tr></tbody></table><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Kemajuan bersama Sepuluh Ribu Ras adalah salah satu tujuan utama Peradaban Simbiosis Jangkar dan juga syarat yang diperlukan untuk kenaikan dimensi global kosmos. Dalam kerangka peradaban simbiosis, setiap ras dapat menemukan jalur evolusinya sendiri, dan keunikan setiap ras dapat dihormati dan diekspresikan. Kemajuan bersama Sepuluh Ribu Ras bukan berarti menghilangkan perbedaan, melainkan mencapai harmoni dalam perbedaan dan mewujudkan simbiosis dalam keragaman.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Deklarasi Peradaban Simbiosis Jangkar)</li><li>50-万族谱系总览 (Gambaran Umum Silsilah Sepuluh Ribu Ras)</li><li>77-万族共和成立 (Pendirian Republik Sepuluh Ribu Ras)</li></ul>',32)])])}const o=e(t,[["render",s]]);export{p as __pageData,o as default};
